import { VertexAI } from '@google-cloud/vertexai';
import {
  ParsedJobMessage,
  OfficialJobData,
  EligibilityResult,
  MatchResult,
  ResumeSelectionResult,
  QuestionClassification
} from '@/schemas/ai';

// Clean local constant definition for schema types, avoiding SDK version import issues
const SchemaType = {
  OBJECT: 'OBJECT',
  STRING: 'STRING',
  INTEGER: 'INTEGER',
  ARRAY: 'ARRAY',
  BOOLEAN: 'BOOLEAN'
} as const;

// Initialize Google Cloud Vertex AI client
// Auto-detects Application Default Credentials (ADC) generated by: gcloud auth application-default login
const vertexAI = new VertexAI({
  project: process.env.GOOGLE_CLOUD_PROJECT || 'gen-lang-client-0208330266',
  location: process.env.GOOGLE_CLOUD_LOCATION || 'us-central1'
});

// Helper to get Gemini model with system instruction and JSON output configuration
function getStructuredModel(systemInstruction: string, responseSchema: any) {
  return vertexAI.getGenerativeModel({
    model: 'gemini-1.5-flash',
    systemInstruction,
    generationConfig: {
      responseMimeType: 'application/json',
      responseSchema,
      temperature: 0.1, // Low temperature for high deterministic accuracy
    }
  });
}

// Helper to safely extract response text from Vertex AI response structure
function getResponseText(result: any): string {
  return result.response.candidates?.[0]?.content?.parts?.[0]?.text || '';
}

// -------------------------------------------------------------
// 1. WhatsApp Parser Model & Schema
// -------------------------------------------------------------
const parsedJobMessageSchema = {
  type: SchemaType.OBJECT,
  properties: {
    company: { type: SchemaType.STRING, description: 'Name of the company hiring' },
    role: { type: SchemaType.STRING, description: 'Job title or role name' },
    location: { type: SchemaType.STRING, description: 'Job location (e.g., Bangalore, remote)' },
    workMode: { type: SchemaType.STRING, enum: ['remote', 'hybrid', 'onsite', 'unknown'] },
    employmentType: { type: SchemaType.STRING, enum: ['full-time', 'internship', 'part-time', 'unknown'] },
    salary: { type: SchemaType.STRING, description: 'Salary details if mentioned' },
    experienceMin: { type: SchemaType.INTEGER, description: 'Minimum years of experience required' },
    experienceMax: { type: SchemaType.INTEGER, description: 'Maximum years of experience if mentioned, else 0' },
    qualifications: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING }, description: 'Required degrees or courses' },
    branches: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING }, description: 'Allowed branches of study' },
    batches: { type: SchemaType.ARRAY, items: { type: SchemaType.INTEGER }, description: 'Eligible graduation batch years (e.g. 2026, 2027)' },
    requiredSkills: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING }, description: 'Mandatory skills required for the role' },
    preferredSkills: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING }, description: 'Preferred/bonus skills' },
    deadline: { type: SchemaType.STRING, description: 'Deadline date string if mentioned' },
    confidenceScore: { type: SchemaType.INTEGER, description: 'Confidence score from 0 to 100' }
  },
  required: ['company', 'role', 'workMode', 'employmentType', 'requiredSkills', 'confidenceScore']
};

const jobMessageParserInstruction = `You are a professional job parser. Your task is to take a raw job post message (usually pasted from a WhatsApp group or channel, which can have emojis, Hinglish text, and messy formatting) and parse it into a clean structured JSON object. 
Ensure you extract the proper company name, role/title, skills, graduation batch years, and experience required. 
If Hinglish or conversational Hindi/English is used, translate the meaning to formal English values. 
Do not fabricate values. If a value is missing, use sensible defaults (like 0 for experience, empty array for skills).`;

export async function aiParseJobMessage(messageText: string): Promise<ParsedJobMessage> {
  const model = getStructuredModel(jobMessageParserInstruction, parsedJobMessageSchema);
  const response = await model.generateContent(`Here is the raw WhatsApp job message:\n\n${messageText}`);
  return JSON.parse(getResponseText(response)) as ParsedJobMessage;
}

// -------------------------------------------------------------
// 2. Official Webpage Reader Model & Schema
// -------------------------------------------------------------
const officialJobDataSchema = {
  type: SchemaType.OBJECT,
  properties: {
    company: { type: SchemaType.STRING },
    role: { type: SchemaType.STRING },
    location: { type: SchemaType.STRING },
    workMode: { type: SchemaType.STRING, enum: ['remote', 'hybrid', 'onsite', 'unknown'] },
    employmentType: { type: SchemaType.STRING, enum: ['full-time', 'internship', 'part-time', 'unknown'] },
    salary: { type: SchemaType.STRING },
    experienceMin: { type: SchemaType.INTEGER },
    experienceMax: { type: SchemaType.INTEGER },
    qualifications: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING } },
    branches: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING } },
    batches: { type: SchemaType.ARRAY, items: { type: SchemaType.INTEGER } },
    requiredSkills: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING } },
    preferredSkills: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING } },
    deadline: { type: SchemaType.STRING },
    atsType: { type: SchemaType.STRING, enum: ['greenhouse', 'lever', 'ashby', 'workday', 'generic', 'unknown'] }
  },
  required: ['company', 'role', 'workMode', 'employmentType', 'requiredSkills', 'atsType']
};

const officialJobPageInstruction = `You are a job requirement extraction agent. You receive raw text content scraped from a corporate careers page (or application form).
Your task is to analyze this text and parse the official job details into the requested JSON schema.
Be conservative:
- If a deadline or salary is not mentioned, use empty string.
- If qualifications or branches are not specified, return empty array.
- Detect the ATS platform type if signatures are present.`;

export async function aiParseOfficialJobPage(pageText: string): Promise<OfficialJobData> {
  const model = getStructuredModel(officialJobPageInstruction, officialJobDataSchema);
  const response = await model.generateContent(`Here is the untrusted scraped job page content:\n\n${pageText}`);
  return JSON.parse(getResponseText(response)) as OfficialJobData;
}

// -------------------------------------------------------------
// 3. Eligibility Checking Engine Model & Schema
// -------------------------------------------------------------
const eligibilityResultSchema = {
  type: SchemaType.OBJECT,
  properties: {
    eligible: { type: SchemaType.BOOLEAN },
    confidenceScore: { type: SchemaType.INTEGER },
    reasons: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING } },
    missingRequirements: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING } }
  },
  required: ['eligible', 'confidenceScore', 'reasons', 'missingRequirements']
};

const eligibilityInstruction = `You are a Job Eligibility Evaluation Engine. Your task is to evaluate if a candidate is eligible for a job based on the candidate's profile and the official job requirements.
CRITICAL SAFETY DIRECTIVES:
1. Never synthesize visa sponsorship or relocations: if the job requires US citizenship or requires relocation and the candidate doesn't have it, mark not eligible.
2. Never convert candidate's project experience into professional employment experience years.
3. Be completely honest. Do not stretch facts.
Classify eligibility as: ELIGIBLE, LIKELY_ELIGIBLE, UNCERTAIN, or NOT_ELIGIBLE. Provide detailed reasons and list any missing requirements.`;

export async function aiCheckEligibility(profile: any, job: any): Promise<EligibilityResult> {
  const model = getStructuredModel(eligibilityInstruction, eligibilityResultSchema);
  const response = await model.generateContent(
    `CANDIDATE PROFILE:\n${JSON.stringify(profile, null, 2)}\n\nJOB REQUIREMENTS:\n${JSON.stringify(job, null, 2)}`
  );
  return JSON.parse(getResponseText(response)) as EligibilityResult;
}

// -------------------------------------------------------------
// 4. Match Score Engine Model & Schema
// -------------------------------------------------------------
const matchResultSchema = {
  type: SchemaType.OBJECT,
  properties: {
    matchScore: { type: SchemaType.INTEGER },
    matchingSkills: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING } },
    missingSkills: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING } },
    strengths: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING } },
    concerns: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING } },
    explanation: { type: SchemaType.STRING }
  },
  required: ['matchScore', 'matchingSkills', 'missingSkills', 'strengths', 'concerns', 'explanation']
};

const matchScoreInstruction = `You are an AI Match Score Evaluator. Your goal is to calculate a semantic match score from 0 to 100 between a candidate's profile and a job description.
Perform semantic skill matching (e.g. if the job requires React and the profile lists JavaScript/React, it is a skill match).
Provide component scores, lists of matching and missing skills, strengths, concerns, and a detailed explanation.
Categorize the recommendation as:
- Strong Match (85-100)
- Good Match (70-84)
- Moderate Match (55-69)
- Weak Match (Below 55)`;

export async function aiCalculateMatchScore(profile: any, job: any): Promise<MatchResult> {
  const model = getStructuredModel(matchScoreInstruction, matchResultSchema);
  const response = await model.generateContent(
    `CANDIDATE PROFILE:\n${JSON.stringify(profile, null, 2)}\n\nJOB DESCRIPTION:\n${JSON.stringify(job, null, 2)}`
  );
  return JSON.parse(getResponseText(response)) as MatchResult;
}

// -------------------------------------------------------------
// 5. Resume Selection Engine Model & Schema
// -------------------------------------------------------------
const resumeSelectionResultSchema = {
  type: SchemaType.OBJECT,
  properties: {
    selectedResumeCategory: { type: SchemaType.STRING, enum: ['Data Analyst', 'BI Analyst', 'AI/ML', 'Python', 'General Tech', 'Custom'] },
    confidenceScore: { type: SchemaType.INTEGER },
    reasons: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING } },
    alternativeCategory: { type: SchemaType.STRING, enum: ['Data Analyst', 'BI Analyst', 'AI/ML', 'Python', 'General Tech', 'Custom'] }
  },
  required: ['selectedResumeCategory', 'confidenceScore', 'reasons']
};

const resumeSelectorInstruction = `You are an AI Resume Selector. You receive the candidate's profile, a list of uploaded resume categories, and the target job description.
Analyze which resume variant best fits the job requirements.
For instance, if the job has a heavy SQL or Python focus, map to Data Analyst or Python. If it's a general fullstack/React role, map to General Tech.
Output the selected category and reasons.`;

export async function aiSelectResume(job: any): Promise<ResumeSelectionResult> {
  const model = getStructuredModel(resumeSelectorInstruction, resumeSelectionResultSchema);
  const response = await model.generateContent(
    `JOB DESCRIPTION:\n${JSON.stringify(job, null, 2)}`
  );
  return JSON.parse(getResponseText(response)) as ResumeSelectionResult;
}

// -------------------------------------------------------------
// 6. Screening Question Classifying Model & Schema
// -------------------------------------------------------------
const questionClassificationSchema = {
  type: SchemaType.OBJECT,
  properties: {
    category: { type: SchemaType.STRING, enum: ['PERSONAL_INFO', 'EDUCATION', 'EXPERIENCE', 'SKILLS', 'SALARY', 'WORK_AUTHORIZATION', 'VISA', 'SPONSORSHIP', 'RELOCATION', 'LEGAL_DECLARATION', 'CRIMINAL_HISTORY', 'DISABILITY', 'VETERAN_STATUS', 'CONFLICT_OF_INTEREST', 'BACKGROUND_CHECK', 'ASSESSMENT', 'UNKNOWN'] },
    normalizedIntent: { type: SchemaType.STRING },
    needsHumanInput: { type: SchemaType.BOOLEAN },
    suggestedAnswer: { type: SchemaType.STRING },
    reasons: { type: SchemaType.STRING }
  },
  required: ['category', 'normalizedIntent', 'needsHumanInput', 'reasons']
};

const questionAnsweringInstruction = `You are a QA Screening Question Engine. You receive a screening question from a job application form and the candidate's profile.
Analyze the question and classify it into a category.
CRITICAL SAFETY INSTRUCTION:
- You MUST set needsHumanInput to true for: 'SALARY', 'WORK_AUTHORIZATION', 'VISA', 'SPONSORSHIP', 'RELOCATION', 'LEGAL_DECLARATION', 'CRIMINAL_HISTORY', 'DISABILITY', 'VETERAN_STATUS', 'CONFLICT_OF_INTEREST', 'BACKGROUND_CHECK', 'ASSESSMENT', 'UNKNOWN'.
- You may only autofill (needsHumanInput: false) for safe profile questions (like email, phone, name), education (GPA, university), and skills if they are verified in the profile.
- Output a normalizedIntent key representing the question goal (e.g. relocation_willingness, visa_sponsorship_needed, notice_period).
- Look at the profile to formulate a suggestedAnswer if possible.`;

export async function aiClassifyQuestion(questionText: string, options: string[] = [], profile: any): Promise<QuestionClassification> {
  const model = getStructuredModel(questionAnsweringInstruction, questionClassificationSchema);
  const response = await model.generateContent(
    `QUESTION:\n"${questionText}"\nOPTIONS (if any):\n${JSON.stringify(options)}\n\nCANDIDATE PROFILE:\n${JSON.stringify(profile, null, 2)}`
  );
  return JSON.parse(getResponseText(response)) as QuestionClassification;
}
